<?php
function apply_beginning_rows($input,$filename,$uid,$stored=null){
 if(setting('beginning_locked','0')==='1')throw new Exception('Beginning Balance is locked.');$pdo=db();$errors=[];$lines=[];$seen=[];
 foreach($input as $row){try{$p=active_product($row['product_id']);$qty=whole_number($row['qty'],'Beginning Quantity');if(isset($seen[$p['id']]))throw new Exception('Duplicate Product Master item.');$seen[$p['id']]=true;$lines[]=['product_id'=>(int)$p['id'],'master_sku'=>$p['master_sku'],'name'=>$p['name'],'new_qty'=>$qty];}catch(Throwable $e){$errors[]='Row '.($row['row']??'?').': '.$e->getMessage();}}
 if(!$lines&&!$errors)$errors[]='No product rows found.';$pdo->beginTransaction();try{$results=[];$save=$pdo->prepare('INSERT INTO beginning_balances(product_id,qty,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE qty=VALUES(qty),updated_by=VALUES(updated_by)');foreach($lines as $line){$q=$pdo->prepare('SELECT qty FROM beginning_balances WHERE product_id=? FOR UPDATE');$q->execute([$line['product_id']]);$line['old_qty']=(int)($q->fetchColumn()?:0);if(!$errors){check_platform_alignment($line['product_id']);$save->execute([$line['product_id'],$line['new_qty'],$uid]);allocate_stock_delta($line['product_id'],$line['new_qty']-$line['old_qty'],'Beginning Balance',date('Y-m-d'));$line['platform_balances']=[];foreach(['Shopee','Lazada','TikTok'] as $pl)$line['platform_balances'][$pl]=platform_qty($pl,$line['product_id']);}$results[]=$line;}
  if(!$errors)foreach($lines as $line)validate_allocation_total($line['product_id']);
  $pdo->prepare('INSERT INTO import_batches(import_type,filename,stored_path,rows_read,units,imported_count,error_count,error_json,result_json,status,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute(['Beginning Balance',$filename,$stored,count($input),$errors?0:array_sum(array_column($lines,'new_qty')),$errors?0:count($lines),count($errors),json_encode($errors),json_encode(['changes'=>$results]),$errors?'Unsuccessful':'Confirmed',$uid]);$bid=(int)$pdo->lastInsertId();audit('Beginning balance update','Import',(string)$bid,$errors?'Rejected; no balances changed':count($lines).' balances updated');$pdo->commit();return [$bid,$errors];
 }catch(Throwable $e){$pdo->rollBack();throw $e;}
}
function beginning_file_input($file){$rows=XlsxReader::rows($file['tmp_name']);$hr=find_header_row($rows,[['item','quantity'],['product','quantity'],['master sku','quantity']]);if($hr===null)throw new Exception('Required: Item/Product/Master SKU and Quantity.');$h=array_flip(array_map('norm',$rows[$hr]));$lines=[];$q=db()->prepare('SELECT id FROM products WHERE master_sku=? OR normalized_name=?');foreach(array_slice($rows,$hr+1) as $i=>$r){if(!array_filter($r,fn($v)=>trim($v)!==''))continue;$sku=trim($r[$h['master sku']??-1]??'');$name=trim($r[$h['item']??$h['product']??-1]??'');$q->execute([$sku,norm($name)]);$ids=$q->fetchAll(PDO::FETCH_COLUMN);if($mapped=product_code_lookup($sku?:$name))$ids=[$mapped];$lines[]=['row'=>$hr+$i+2,'product_id'=>count($ids)===1?(int)$ids[0]:0,'qty'=>$r[$h['quantity']]??''];}return $lines;}

